import AppKit

final class ClipboardMonitor {
    private let pasteboard = NSPasteboard.general
    private var lastChange: Int
    private var ignoredChange: Int?
    private var timer: Timer?

    private let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    init() { lastChange = pasteboard.changeCount }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.3, repeats: true) { [weak self] _ in self?.check() }
    }

    /// Call after the app itself writes to the pasteboard so that write isn't recorded.
    func ignoreCurrentChange() { ignoredChange = pasteboard.changeCount }

    private func check() {
        let count = pasteboard.changeCount
        guard count != lastChange else { return }
        lastChange = count
        if count == ignoredChange { return }
        let settings = Settings.shared
        if settings.paused { return }

        let types = pasteboard.types ?? []
        if types.contains(where: { skipTypes.contains($0.rawValue) }) { return }
        if types.contains(.fileURL) { return }

        if let text = pasteboard.string(forType: .string) {
            guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                  text.utf8.count <= settings.maxTextBytes else { return }
            let limit = settings.maxTextBytes
            let rtf = pasteboard.data(forType: .rtf).flatMap { $0.count <= limit ? $0 : nil }
            let html = pasteboard.data(forType: .html).flatMap { $0.count <= limit ? $0 : nil }
            HistoryStore.shared.addText(text, rtf: rtf, html: html)
        } else if let png = imagePNG(), png.count <= settings.maxImageBytes {
            HistoryStore.shared.addImage(png: png)
        }
    }

    private func imagePNG() -> Data? {
        if let png = pasteboard.data(forType: .png) { return png }
        if let tiff = pasteboard.data(forType: .tiff), let rep = NSBitmapImageRep(data: tiff) {
            return rep.representation(using: .png, properties: [:])
        }
        return nil
    }
}
